import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import { getAuth } from 'firebase/auth';
import { HighlightRequestError, requestAccountHighlights } from '../services/wordpress';
import { DEFAULT_HIGHLIGHTS, HighlightChange, HighlightDocument, parseHighlightDocument } from '../utils/highlights';

type HighlightContextValue = {
  document: HighlightDocument; ready: boolean; hasSnapshot: boolean; loading: boolean; saving: boolean;
  error: string | null;
  refresh: () => Promise<void>; change: (change: HighlightChange, expectedRevision?: number) => Promise<boolean>;
  clearLocalCache: () => void;
};
const HighlightContext = createContext<HighlightContextValue | null>(null);
export const highlightCacheKey = (uid: string) => `revelationary.highlights.v1:${uid}`;

export function HighlightProvider({ uid, wpToken, children }: { uid: string | null; wpToken: string | null; children: React.ReactNode }) {
  const cacheKey = uid ? highlightCacheKey(uid) : null;
  const [snapshot, setSnapshot] = useState<HighlightDocument | null>(() => {
    try { const raw = cacheKey && localStorage.getItem(cacheKey); return raw ? parseHighlightDocument(JSON.parse(raw)) : null; } catch { return null; }
  });
  const snapshotRef = useRef(snapshot);
  const [ready, setReady] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const alive = useRef(true);
  const busy = useRef(false);
  const controller = useRef<AbortController | null>(null);
  const retry = useRef<{ revision: number; operationId: string; change: HighlightChange } | null>(null);
  const current = useCallback(() => alive.current && !!uid && getAuth().currentUser?.uid === uid, [uid]);
  const install = useCallback((value: HighlightDocument) => {
    snapshotRef.current = value; setSnapshot(value);
    try { if (cacheKey) localStorage.setItem(cacheKey, JSON.stringify(value)); } catch { /* Server persistence is authoritative even if local storage is full. */ }
  }, [cacheKey]);
  const refresh = useCallback(async () => {
    if (!uid || !wpToken || busy.current) return;
    controller.current?.abort();
    const request = new AbortController(); controller.current = request;
    setLoading(true);
    try {
      const value = await requestAccountHighlights(undefined, request.signal);
      if (!request.signal.aborted && current()) { install(value); setReady(true); setError(null); }
    } catch (failure) {
      if (!request.signal.aborted && current()) setError(failure instanceof Error ? failure.message : 'Highlights could not be loaded.');
    } finally { if (!request.signal.aborted && current()) setLoading(false); }
  }, [uid, wpToken, current, install]);
  useEffect(() => {
    alive.current = true;
    void refresh();
    const onFocus = () => { if (window.document.visibilityState === 'visible') void refresh(); };
    const onStorage = (event: StorageEvent) => { if (event.key === cacheKey) void refresh(); };
    window.addEventListener('focus', onFocus);
    window.addEventListener('online', onFocus);
    window.addEventListener('storage', onStorage);
    window.document.addEventListener('visibilitychange', onFocus);
    return () => {
      alive.current = false; controller.current?.abort();
      window.removeEventListener('focus', onFocus); window.removeEventListener('online', onFocus);
      window.removeEventListener('storage', onStorage); window.document.removeEventListener('visibilitychange', onFocus);
    };
  }, [refresh, cacheKey]);
  const change = async (intent: HighlightChange, expectedRevision?: number): Promise<boolean> => {
    if (!current() || !wpToken || !ready || !snapshotRef.current || busy.current) return false;
    busy.current = true; setSaving(true); setError(null);
    controller.current?.abort(); setLoading(false);
    const request = new AbortController(); controller.current = request;
    const previous = retry.current;
    const operation = previous && JSON.stringify(previous.change) === JSON.stringify(intent) ? previous : {
      revision: expectedRevision ?? snapshotRef.current.revision, operationId: crypto.randomUUID(), change: intent,
    };
    retry.current = operation;
    try {
      const result = await requestAccountHighlights(operation, request.signal);
      if (!current() || request.signal.aborted) return false;
      install(result); retry.current = null;
      return true;
    } catch (failure) {
      if (!current() || request.signal.aborted) return false;
      if (failure instanceof HighlightRequestError && failure.status === 409) {
        retry.current = null;
        try { const latest = await requestAccountHighlights(undefined, request.signal); if (current() && !request.signal.aborted) install(latest); }
        catch {
          if (current()) { setReady(false); setError('Highlights changed elsewhere, but the latest version could not be loaded. Reload before retrying.'); }
          return false;
        }
      }
      if (current() && !request.signal.aborted) setError(failure instanceof Error ? failure.message : 'Your highlight was not saved. Please retry.');
      return false;
    } finally {
      busy.current = false;
      if (current()) setSaving(false);
    }
  };
  const clearLocalCache = () => {
    controller.current?.abort(); retry.current = null;
    try { if (cacheKey) localStorage.removeItem(cacheKey); } catch { /* No local cache available. */ }
    snapshotRef.current = null; setSnapshot(null); setReady(false);
  };
  return <HighlightContext.Provider value={{ document: snapshot || DEFAULT_HIGHLIGHTS, ready, hasSnapshot: !!snapshot, loading, saving, error, refresh, change, clearLocalCache }}>{children}</HighlightContext.Provider>;
}
export function useAccountHighlights() {
  const context = useContext(HighlightContext);
  if (!context) throw new Error('Highlights require HighlightProvider.');
  return context;
}
