type AnalyticsParams = Record<string, string | number | boolean>;

declare global {
  interface Window {
    gtag?: (...args: unknown[]) => void;
  }
}

/** Fire a GA4 event when gtag is loaded (deferred until interaction in production). */
export function trackEvent(eventName: string, params?: AnalyticsParams): void {
  if (typeof window === "undefined" || typeof window.gtag !== "function") {
    return;
  }
  window.gtag("event", eventName, params);
}

export const ConversionEvents = {
  scrollSignupShown: () => trackEvent("scroll_signup_shown"),
  scrollSignupDismissed: () => trackEvent("scroll_signup_dismissed"),
  signInModalOpen: (source: string) =>
    trackEvent("sign_in_modal_open", { source }),
  signUpComplete: (method: "google" | "email", source: string) =>
    trackEvent("sign_up_complete", { method, source }),
  loginComplete: (method: "google" | "email") =>
    trackEvent("login_complete", { method }),
} as const;
