import type { CSSProperties } from "react";
import type { SxProps, Theme } from "@mui/material/styles";
import { alpha } from "@mui/material/styles";

/** Frosted pill container for verse action buttons. */
export const verseActionBarSx = (hasDropCap: boolean): SxProps<Theme> => (theme) => ({
  position: "absolute",
  top: hasDropCap ? "-3.5rem" : "-2.75rem",
  left: 0,
  display: "inline-flex",
  alignItems: "center",
  flexDirection: "row",
  gap: { xs: 0.15, sm: 0.25 },
  transform: "translateY(-100%)",
  marginLeft: { xs: 2, sm: 4 },
  zIndex: 12,
  pointerEvents: "auto",
  padding: "4px 6px",
  borderRadius: "999px",
  backgroundColor:
    theme.palette.mode === "light"
      ? alpha("#ffffff", 0.94)
      : alpha("#2a2a2a", 0.92),
  border: `1px solid ${
    theme.palette.mode === "light"
      ? alpha("#000000", 0.08)
      : alpha("#ffffff", 0.1)
  }`,
  boxShadow:
    theme.palette.mode === "light"
      ? "0 2px 12px rgba(0, 0, 0, 0.08)"
      : "0 2px 12px rgba(0, 0, 0, 0.35)",
  backdropFilter: "blur(10px)",
  WebkitBackdropFilter: "blur(10px)",
});

/** Compact icon button inside the verse action bar. */
export const verseActionButtonSx: SxProps<Theme> = {
  width: { xs: 36, sm: 38 },
  height: { xs: 36, sm: 38 },
  padding: 0.75,
  opacity: 0.88,
  color: (theme) =>
    theme.palette.mode === "light" ? "#212121" : "#f5f5f5",
  transition: "opacity 0.2s ease, transform 0.2s ease, background-color 0.2s ease",
  "&:hover": {
    opacity: 1,
    transform: "scale(1.06)",
    backgroundColor: (theme) =>
      theme.palette.mode === "light"
        ? alpha("#000000", 0.05)
        : alpha("#ffffff", 0.08),
  },
  "&:active": {
    transform: "scale(0.96)",
  },
  "&.Mui-disabled": {
    opacity: 0.45,
  },
};

/** Comment indicator beside a verse — original flat chip (not pill). */
export const verseCommentChipSx = (
  isSelected: boolean,
): SxProps<Theme> => (theme) => ({
  display: "flex",
  flexDirection: "row",
  alignItems: "center",
  position: "absolute",
  left: -25,
  top: { xs: -20, sm: -18 },
  backgroundColor:
    theme.palette.mode === "light" ? "#f5f5f5" : theme.palette.grey[900],
  padding: { xs: "3px 6px", sm: "5px" },
  borderRadius: "5px",
  ml: { xs: 1, sm: 2 },
  cursor: "pointer",
  opacity: isSelected ? 0 : 1,
  transition: "opacity 0.3s ease-in-out, background-color 0.2s ease-in-out",
  pointerEvents: isSelected ? "none" : "auto",
  "&:hover": {
    backgroundColor:
      theme.palette.mode === "light" ? "#e0e0e0" : theme.palette.grey[800],
    opacity: isSelected ? 0 : 1,
  },
  "&:active": {
    opacity: 0.8,
  },
});

export const verseCommentIconSx = (
  hasCount: boolean,
): SxProps<Theme> => ({
  fontSize: { xs: "0.75rem", sm: "0.9rem" },
  mr: hasCount ? { xs: 0.5, sm: 0.75 } : 0,
  color: (theme) =>
    theme.palette.mode === "light" ? "#555555" : "#e5e5e5",
});

export const verseSelectedHighlightStyle = (
  isDarkMode: boolean,
): CSSProperties => ({
  backgroundColor: isDarkMode ? "rgba(255, 255, 255, 0.15)" : "rgba(0, 0, 0, 0.08)",
  borderRadius: "4px",
  padding: "2px 4px",
});
