// Profile operations use the signed-in user's application password, never a
// deployment credential or a bearer/JWT interpretation of that password.
const profileSession = () => {
  const user = getAuth().currentUser;
  const token = getStoredWordPressAppPassword();
  const id = Number(Cookies.get('userId'));
  if (!user?.email || !token || !Number.isInteger(id) || id <= 0) {
    throw new Error('Your profile session is unavailable. Please sign in again.');
  }
  const assertCurrent = () => {
    if (getAuth().currentUser?.uid !== user.uid ||
        getStoredWordPressAppPassword() !== token || Number(Cookies.get('userId')) !== id) {
      throw new Error('Your account changed. Please reopen your profile.');
    }
  };
  return { id, assertCurrent, authorization: `Basic ${btoa(`${user.email}:${token}`)}` };
};

export type EditableWordPressProfile = WordPressUser & {
  name: string;
  description: string;
  capabilities?: { upload_files?: boolean };
};

const profileRequest = async (userId: number, data?: { name: string; description: string }, signal?: AbortSignal): Promise<EditableWordPressProfile> => {
  const session = profileSession();
  if (session.id !== userId) throw new Error('The requested profile does not match your account.');
  const response = await fetch(`${WP_API_URL}/users/me?context=edit`, {
    method: data ? 'POST' : 'GET', signal,
    headers: { Authorization: session.authorization, 'Content-Type': 'application/json' },
    ...(data ? { body: JSON.stringify(data) } : {}),
  });
  session.assertCurrent();
  if (response.status === 401) throw new Error('Your WordPress session was not accepted. Please sign out and sign in again.');
  if (!response.ok) throw new Error(data ? 'Your profile could not be saved. Your changes are still here; please retry.' : 'Your profile could not be loaded. Please retry.');
  const profile = await response.json();
  session.assertCurrent();
  if (profile.id !== session.id || typeof profile.name !== 'string' || typeof profile.description !== 'string') {
    throw new Error('The profile response did not match your account.');
  }
  return profile;
};

export const getWordPressProfile = (userId: number, signal?: AbortSignal) => profileRequest(userId, undefined, signal);
export const updateWordPressProfile = (userId: number, data: { name: string; description: string }) => profileRequest(userId, data);

export type ProfileComment = {
  id: number; author: number; post: number; parent: number; date: string;
  content: { rendered: string }; verseReference?: string; post_name?: string; post_title?: string;
  _embedded?: Record<string, Array<{ title?: { rendered: string }; slug?: string }>>;
};
export type ProfileCommentPage = { comments: ProfileComment[]; total: number; totalPages: number; page: number };

export const getUserCommentsPage = async (page = 1, signal?: AbortSignal): Promise<ProfileCommentPage> => {
  const session = profileSession();
  if (!Number.isInteger(page) || page < 1) throw new Error('Invalid comments page.');
  const query = new URLSearchParams({ page: String(page), per_page: '20' });
  const base = WP_API_URL?.replace(/\/wp\/v2\/?$/, '');
  const response = await fetch(`${base}/revelationary/v1/me/comments?${query}`, {
    headers: { Authorization: session.authorization }, signal,
  });
  session.assertCurrent();
  if (response.status === 401) throw new Error('Your WordPress session was not accepted. Please sign out and sign in again.');
  if (response.status === 404) throw new Error('Your comments are unavailable until the profile service is updated.');
  if (!response.ok) throw new Error('Your comments could not be loaded. Please retry.');
  const comments = await response.json();
  session.assertCurrent();
  const totalHeader = response.headers.get('X-WP-Total');
  const pagesHeader = response.headers.get('X-WP-TotalPages');
  const total = Number(totalHeader), totalPages = Number(pagesHeader);
  if (!Array.isArray(comments) || comments.some(c => c.author !== session.id || !Number.isInteger(c.id)) ||
      totalHeader === null || pagesHeader === null || !Number.isInteger(total) || total < comments.length ||
      !Number.isInteger(totalPages) || totalPages < 0 || (comments.length > 0 && totalPages < page)) {
    throw new Error('Comment totals are unavailable. Please retry.');
  }
  return { comments, total, totalPages, page };
};

export const deleteProfileComment = async (commentId: number) => {
  const session = profileSession();
  // Confirm ownership with the server before requesting the normal trash action.
  const existing = await fetch(`${WP_API_URL}/comments/${commentId}`, { headers: { Authorization: session.authorization } });
  const comment = existing.ok ? await existing.json() : null;
  session.assertCurrent();
  if (comment?.author !== session.id) throw new Error('This comment cannot be deleted from your profile.');
  const response = await fetch(`${WP_API_URL}/comments/${commentId}`, { method: 'DELETE', headers: { Authorization: session.authorization } });
  session.assertCurrent();
  if (!response.ok) throw new Error('Your comment could not be deleted. Please retry.');
};

export const uploadProfileImage = async (file: File): Promise<string> => {
  const session = profileSession();
  const profile = await getWordPressProfile(session.id);
  if (!profile.capabilities?.upload_files) throw new Error('Photo uploads are not enabled for this account.');
  if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type) || file.size > 5 * 1024 * 1024) {
    throw new Error('Choose a JPG, PNG or WebP image smaller than 5 MB.');
  }
  session.assertCurrent();
  const formData = new FormData();
  formData.append('file', file);
  formData.append('title', `profile-photo-${Date.now()}`);
  const response = await fetch(`${WP_API_URL}/media`, {
    method: 'POST', headers: { Authorization: session.authorization }, body: formData,
  });
  session.assertCurrent();
  if (!response.ok) throw new Error('Your photo could not be uploaded. Your previous photo is unchanged.');
  const data = await response.json();
  session.assertCurrent();
  if (typeof data.source_url !== 'string' || !data.source_url.startsWith('https://')) throw new Error('The uploaded photo URL is unavailable.');
  // Never delete old media here: the new URL has not yet been saved to Firebase.
  return data.source_url;
};

// Account-owned highlights share the established application-password boundary.
export class HighlightRequestError extends Error {
  constructor(message: string, public status: number) { super(message); }
}
export const requestAccountHighlights = async (
  update?: { revision: number; operationId: string; change: import('../utils/highlights').HighlightChange },
  signal?: AbortSignal,
): Promise<import('../utils/highlights').HighlightDocument> => {
  const session = profileSession();
  const base = WP_API_URL?.replace(/\/wp\/v2\/?$/, '');
  const response = await fetch(`${base}/revelationary/v1/me/highlights`, {
    method: update ? 'PUT' : 'GET', signal, cache: 'no-store',
    headers: { Authorization: session.authorization, 'Content-Type': 'application/json' },
    ...(update ? { body: JSON.stringify(update) } : {}),
  });
  session.assertCurrent();
  if (!response.ok) {
    const message = response.status === 404 ? 'Account highlights need the WordPress update before they can sync.'
      : response.status === 409 ? 'Highlights changed elsewhere. The latest version has been loaded; review it and retry your change.'
      : response.status === 401 ? 'Your WordPress session expired. Sign in again to sync highlights.'
      : update ? 'Your change was not confirmed as saved. Please retry.' : 'Highlights could not be refreshed. Please retry.';
    throw new HighlightRequestError(message, response.status);
  }
  const body: unknown = await response.json();
  session.assertCurrent();
  if (!body || typeof body !== 'object' || (body as { owner?: unknown }).owner !== session.id) throw new Error('The highlights response did not match your account.');
  return parseHighlightDocument(body);
};
