/**
 * Strong's Concordance Service
 * Fetches Strong's definitions from static CDN files
 * 
 * Data source: bible-strongs/ (served via jsdelivr CDN)
 * License: Public domain (Strong's Concordance, published 1890)
 */

const STRONGS_CDN_BASE = 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-strongs@main';

export interface StrongsEntry {
  number: string;
  language: 'hebrew' | 'greek';
  transliteration?: string;
  pronunciation?: string;
  definition: string;
  kjvTranslation?: string;
  hebrew?: string; // Hebrew text (lemma) for Hebrew entries
  greek?: string; // Greek text (lemma) for Greek entries
  verses?: string[]; // Array of verse references in format "book chapter:verse:position"
  translations?: Record<string, string>; // All language translations: { 'zh': '...', 'de': '...', 'es': '...', etc. }
}

/**
 * Determine if a Strong's number is Hebrew or Greek
 */
function getStrongsLanguage(strongsNumber: string): 'hebrew' | 'greek' {
  return strongsNumber.startsWith('H') ? 'hebrew' : 'greek';
}

/**
 * Fetch Strong's entry - tries local (public/bible-strongs) first, then CDN
 */
export const fetchStrongsEntry = async (
  strongsNumber: string
): Promise<StrongsEntry | null> => {
  if (!strongsNumber) {
    return null;
  }

  // Normalize Strong's number (ensure proper format: H0001, G0001, etc.)
  const normalized = strongsNumber.toUpperCase().trim();
  const language = getStrongsLanguage(normalized);
  const langPath = language === 'hebrew' ? 'hebrew' : 'greek';
  
  const urls = [
    `/bible-strongs/${langPath}/entries/${normalized}.json`,
    `${STRONGS_CDN_BASE}/${langPath}/entries/${normalized}.json`,
  ];

  for (const url of urls) {
    try {
      const response = await fetch(url);
      if (response.ok) {
        const data = await response.json();
        return data as StrongsEntry;
      }
    } catch (error) {
      // Try next URL
      continue;
    }
  }

  console.warn(`Strong's ${normalized} not found from local or CDN`);
  return null;
};

/**
 * Get Strong's definition in the user's language
 * Supports all DeepL languages
 */
export const getStrongsDefinition = (
  entry: StrongsEntry | null,
  userLanguage = 'en'
): string => {
  if (!entry) {
    return '';
  }

  // Map common language codes
  const langMap: Record<string, string> = {
    'en': 'en',
    'zh': 'zh', 'zh-hans': 'zh', 'zh-hant': 'zh', 'cuv': 'zh',
    'de': 'de', 'lut': 'de',
    'es': 'es', 'fr': 'fr', 'it': 'it', 'pt': 'pt', 'ru': 'ru',
    'ja': 'ja', 'ko': 'ko', 'ar': 'ar', 'hi': 'hi',
    // Add more mappings as needed
  };

  const normalizedLang = langMap[userLanguage.toLowerCase()] || userLanguage.toLowerCase();

  // Return translated definition if available, otherwise English
  if (normalizedLang !== 'en' && entry.translations?.[normalizedLang]) {
    return entry.translations[normalizedLang];
  }

  // Default to English definition
  return entry.definition || entry.kjvTranslation || '';
};

/**
 * Fetch multiple Strong's entries
 */
export const fetchStrongsEntries = async (
  strongsNumbers: string[]
): Promise<Map<string, StrongsEntry>> => {
  const entries = new Map<string, StrongsEntry>();

  // Fetch all entries in parallel
  const promises = strongsNumbers.map(async (number) => {
    const entry = await fetchStrongsEntry(number);
    if (entry) {
      entries.set(number, entry);
    }
  });

  await Promise.all(promises);
  return entries;
};

/**
 * Get Strong's definition for a word (with caching)
 * Supports all DeepL languages
 */
const strongsCache = new Map<string, StrongsEntry | null>();

export const getStrongsDefinitionForWord = async (
  strongsNumber: string,
  userLanguage = 'en'
): Promise<string> => {
  if (!strongsNumber) {
    return '';
  }

  // Check cache first
  let entry = strongsCache.get(strongsNumber);
  
  if (!entry && entry !== null) {
    // Not in cache, fetch it
    entry = await fetchStrongsEntry(strongsNumber);
    strongsCache.set(strongsNumber, entry);
  }

  return getStrongsDefinition(entry, userLanguage);
};

/**
 * Parse verse reference with position: "genesis 1:1:2" -> { book: "genesis", chapter: 1, verse: 1, position: 2 }
 */
export interface ParsedVerseRef {
  book: string;
  chapter: number;
  verse: number;
  position?: number;
}

export const parseVerseRef = (verseRef: string): ParsedVerseRef | null => {
  const parts = verseRef.split(' ');
  if (parts.length < 2) return null;
  
  const book = parts.slice(0, -1).join(' ');
  const lastPart = parts[parts.length - 1];
  
  // Check if it has position: "1:1:2" format
  const positionMatch = lastPart.match(/^(\d+):(\d+):(\d+)$/);
  if (positionMatch) {
    return {
      book,
      chapter: parseInt(positionMatch[1]),
      verse: parseInt(positionMatch[2]),
      position: parseInt(positionMatch[3])
    };
  }
  
  // Regular format: "1:1"
  const regularMatch = lastPart.match(/^(\d+):(\d+)$/);
  if (regularMatch) {
    return {
      book,
      chapter: parseInt(regularMatch[1]),
      verse: parseInt(regularMatch[2])
    };
  }
  
  return null;
};

/**
 * Word information for displaying Hebrew text in a verse
 */
export interface VerseWord {
  strongsNumber: string;
  hebrew: string;
  position: number;
  entry: StrongsEntry;
}

/**
 * Verse index cache (loaded on-demand)
 */
let verseIndexCache: Record<string, string[]> | null = null;

/**
 * Load verse index from CDN
 */
const loadVerseIndex = async (): Promise<Record<string, string[]>> => {
  if (verseIndexCache) {
    return verseIndexCache;
  }
  
  // Try CDN first, then fallback to local public folder for development
  const urls = [
    `${STRONGS_CDN_BASE}/verse-index.json`,
    '/bible-strongs/verse-index.json', // Local fallback for development
  ];
  
  for (const url of urls) {
    try {
      const response = await fetch(url);
      if (response.ok) {
        const index = await response.json();
        verseIndexCache = index as Record<string, string[]>;
        return verseIndexCache;
      }
    } catch (error) {
      // Continue to next URL
      continue;
    }
  }
  
  console.warn('Verse index not found from CDN or local. Make sure verse-index.json is deployed or in public/bible-strongs/');
  return {};
};

/**
 * Get all Hebrew words for a specific verse, sorted by position
 * Replaces IQ Bible API fetchOriginalText functionality
 */
export const fetchHebrewWordsForVerse = async (
  book: string,
  chapter: number,
  verse: number
): Promise<VerseWord[]> => {
  try {
    // Normalize book: trim, collapse spaces, lowercase for lookup
    const bookTrimmed = (book || '').trim().replace(/\s+/g, ' ');
    let normalizedBook = bookTrimmed.toLowerCase().replace(/\s+/g, '');
    
    // Handle book name variations - map common formats to lowercase format used in verse index
    const bookNameMap: Record<string, string> = {
      'firstsamuel': 'firstsamuel',
      '1samuel': 'firstsamuel',
      'secondsamuel': 'secondsamuel',
      '2samuel': 'secondsamuel',
      'firstkings': 'firstkings',
      '1kings': 'firstkings',
      'secondkings': 'secondkings',
      '2kings': 'secondkings',
      'firstchronicles': 'firstchronicles',
      '1chronicles': 'firstchronicles',
      'secondchronicles': 'secondchronicles',
      '2chronicles': 'secondchronicles',
    };
    
    normalizedBook = bookNameMap[normalizedBook] || normalizedBook;
    
    // Load verse index to get Strong's numbers for this verse
    const verseIndex = await loadVerseIndex();
    
    // Verse index keys are like "genesis 1:1" or "firstSamuel 1:1"
    const possibleKeys = [
      `${normalizedBook} ${chapter}:${verse}`,
      `${bookTrimmed} ${chapter}:${verse}`,
      `${bookTrimmed.toLowerCase()} ${chapter}:${verse}`,
    ];
    let strongsNumbers: string[] = [];
    for (const key of possibleKeys) {
      if (verseIndex[key]) {
        strongsNumbers = verseIndex[key];
        break;
      }
    }
    
    // If still not found, do case-insensitive search
    if (strongsNumbers.length === 0) {
      const targetPattern = new RegExp(`^${normalizedBook.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s+${chapter}:${verse}$`, 'i');
      for (const [key, numbers] of Object.entries(verseIndex)) {
        if (targetPattern.test(key)) {
          strongsNumbers = numbers;
          break;
        }
      }
    }
    
    if (strongsNumbers.length === 0) {
      console.warn(`No Hebrew words found for verse: ${book} ${chapter}:${verse}. Tried keys: ${possibleKeys.join(', ')}`);
      return [];
    }
    
    // Use the existing function to get words with positions
    const words = await getHebrewWordsForVerse(bookTrimmed, chapter, verse, strongsNumbers);
    
    if (words.length === 0) {
      console.warn(`No Hebrew words with positions found for verse: ${book} ${chapter}:${verse}`);
    }
    
    return words;
  } catch (error) {
    console.error('Error fetching Hebrew words for verse:', error);
    return [];
  }
};

/**
 * Get Hebrew words for a verse given Strong's numbers
 * This is the recommended approach - use known Strong's numbers from verse data
 */
export const getHebrewWordsForVerse = async (
  book: string,
  chapter: number,
  verse: number,
  strongsNumbers: string[]
): Promise<VerseWord[]> => {
  // Normalize book name: trim and collapse multiple spaces, then lowercase
  const normalizedBook = (book || '').toLowerCase().trim().replace(/\s+/g, ' ');
  
  const words: VerseWord[] = [];
  
  // Fetch all Strong's entries in parallel
  const entries = await fetchStrongsEntries(strongsNumbers);
  
  // Extract words that appear in this verse, with their positions
  // Note: entries may use camelCase (e.g., "firstSamuel") while normalizedBook is lowercase
  // We need to match case-insensitively
  const normalizedBookLower = normalizedBook.toLowerCase();
  
  for (const [strongsNumber, entry] of entries.entries()) {
    if (!entry.verses || entry.verses.length === 0 || !entry.hebrew) continue;
    
    for (const verseRef of entry.verses) {
      const parsed = parseVerseRef(verseRef);
      if (!parsed) continue;
      
      const entryBookNormalized = parsed.book.toLowerCase().trim().replace(/\s+/g, ' ');
      const matchesBook = entryBookNormalized === normalizedBookLower;
      const matchesChapter = Number(parsed.chapter) === Number(chapter);
      const matchesVerse = Number(parsed.verse) === Number(verse);
      const hasPosition = parsed.position !== undefined;
      
      if (matchesBook && matchesChapter && matchesVerse && hasPosition && parsed.position !== undefined) {
        words.push({
          strongsNumber,
          hebrew: entry.hebrew,
          position: parsed.position,
          entry
        });
        break;
      }
    }
  }
  
  // Sort by position to get correct word order
  words.sort((a, b) => a.position - b.position);
  
  return words;
};
